const processedArray = applyCast(data.pre, data.src);
return out(find(processedArray, data.fnc));
*/
// ===============================================================================
// find(...) – Apply Mode
// ===============================================================================
return function(value, testFunction) {
   testFunction = data.rp1 ? testFunction : data.fnc;
   return out(find(value, testFunction));
};


